#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
#include <iomanip>

void bubbleSort(std::vector<unsigned int>& a) {
    const size_t size = a.size();
    for (size_t pass = 1; pass < size; ++pass) {
        for (size_t j = 0; j < size - 1; ++j) {
            if (a[j] > a[j + 1]) {
                std::swap(a[j], a[j + 1]);
            }
        }
    }
}

void computeMedian(std::vector<unsigned int> responses) {
    std::cout << "********\n Median\n********\n";
    bubbleSort(responses);
    size_t mid = responses.size() / 2;
    std::cout << "Sorted median element: " << responses[mid] << "\n\n";
}

void computeMode(const std::vector<unsigned int>& responses) {
    std::cout << "********\n  Mode\n********\n";
    std::array<unsigned int, 10> freq{};
    for (unsigned int val : responses) {
        if (val >= 1 && val <= 9) {
            ++freq[val];
        }
    }

    std::cout << std::setw(8) << "Response" << std::setw(11) << "Frequency" << "  Histogram\n";
    unsigned int largest = 0;
    unsigned int modeVal = 0;

    for (size_t r = 1; r <= 9; ++r) {
        std::cout << std::setw(8) << r << std::setw(11) << freq[r] << "  ";
        if (freq[r] > largest) {
            largest = freq[r];
            modeVal = static_cast<unsigned int>(r);
        }
        for (unsigned int h = 0; h < freq[r]; ++h) {
            std::cout << '*';
        }
        std::cout << '\n';
    }
    std::cout << "\nMode: " << modeVal << " with " << largest << " occurrences.\n";
}

int main() {
    std::vector<unsigned int> data = {6, 7, 8, 9, 8, 7, 8, 9, 8, 7, 8, 8, 2, 5, 3};
    computeMedian(data);
    computeMode(data);
    return 0;
}

#include <iostream>
#include <vector>
#include <optional>

std::optional<size_t> linearSearch(const std::vector<int>& data, int key) {
    for (size_t i = 0; i < data.size(); ++i) {
        if (data[i] == key) {
            return i; // found: return index wrapped in optional
        }
    }
    return std::nullopt; // not found
}

int main() {
    constexpr size_t SIZE = 10;
    std::vector<int> a(SIZE);
    for (size_t x = 0; x < SIZE; ++x) {
        a[x] = static_cast<int>(2 * x);
    }

    int searchKey1 = 8;
    auto result1 = linearSearch(a, searchKey1);
    if (result1.has_value()) {
        std::cout << "Key " << searchKey1 << " found at index " << *result1 << "\n";
    } else {
        std::cout << "Key " << searchKey1 << " not found\n";
    }

    int searchKey2 = 15;
    auto result2 = linearSearch(a, searchKey2);
    if (result2.has_value()) {
        std::cout << "Key " << searchKey2 << " found at index " << *result2 << "\n";
    } else {
        std::cout << "Key " << searchKey2 << " not found\n";
    }

    return 0;
}
